const crypto = require('crypto');

function extractJSON(text) {
  text = String(text || '').replace(/<think>[\s\S]*?<\/think>/g, '');
  const candidates = [];
  let depth = 0, start = -1, inStr = false, esc = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (depth > 0 && inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (depth > 0 && c === '"') { inStr = true; continue; }
    if (c === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (c === '}' && depth > 0) {
      depth--;
      if (depth === 0) candidates.push(text.slice(start, i + 1));
    }
  }

  let best = null;
  for (const s of candidates) {
    try {
      const o = JSON.parse(s);
      if (!best || s.length > best.len) best = { o, len: s.length };
    } catch (e) {}
  }
  if (!best) throw new Error('No valid JSON in AI response: ' + text.slice(0, 300));
  return best.o;
}

const form = $('Webhook').first().json.body || {};
const item = $input.first().json;
const raw = item.choices?.[0]?.message?.content || item.content?.parts?.[0]?.text || item.text || '';
const cv = extractJSON(raw);

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(form.password, salt, 64).toString('hex');

return [{
  json: {
    username: form.name,
    password_hash: salt + ':' + hash,
    jobTitle: form.jobTitle,
    name: cv.name,
    email: cv.email,
    phone: "'" + (cv.phone || ''),
    location: cv.location,
    links: JSON.stringify(cv.links),
    summary: cv.summary,
    experience: JSON.stringify(cv.experience),
    education: JSON.stringify(cv.education),
    certificates: JSON.stringify(cv.certificates),
    projects: JSON.stringify(cv.projects),
