const ai = $input.all();

const urlFor = (platform, q) => {
  const e = encodeURIComponent(q);
  switch (platform) {
    case 'Udemy': return `https://www.udemy.com/courses/search/?q=${e}`;
    case 'edX': return `https://www.edx.org/search?q=${e}`;
    case 'LinkedIn Learning': return `https://www.linkedin.com/learning/search?keywords=${e}`;
    default: return `https://www.coursera.org/search?query=${e}`;
  }
};

const clamp = (n) => Math.max(0, Math.min(100, Number(n) || 0));
const levelOf = d => d <= 2 ? 'Beginner' : d === 3 ? 'Intermediate' : 'Advanced';

const result = ai.map((item, i) => {
  let job;
  try {
    job = $('HTTP Request').itemMatching(i).json;
  } catch (e) {
    job = $('HTTP Request').all()[i]?.json || {};
  }

  const raw = item.json.choices?.[0]?.message?.content || '';
  let r = {};
  let parsed = true;
  try {
    r = extractJSON(raw);
  } catch (e) {
    parsed = false;
  }

  const skills = (Array.isArray(r.skills) ? r.skills : [])
    .map(s => (typeof s === 'string' ? { skill: s } : s))
    .filter(s => s && s.skill)
    .map(s => {
      const difficulty = Math.max(1, Math.min(5, Number(s.difficulty) || 3));
      return {
        skill: s.skill,
        difficulty,
        level: levelOf(difficulty),
        desskill: s.desskill || '',
        urlskill: urlFor(s.platform, s.courseSearch || s.skill)
      };
    })
    .sort((a, b) => a.difficulty - b.difficulty);

  return {
    json: {
      title: job.title,
      companyName: job.companyName,
      postedAt: job.postedAt,
      link: job.link,
      matchScore: clamp(r.matchScore),
      summary: r.summary || '',
      skills,
      ...(parsed ? {} : { error: 'AI response was not valid JSON' })
    }
  };
});

result.sort((a, b) => b.json.matchScore - a.json.matchScore);
return result;

