const levelOf = d => d <= 2 ? 'Beginner' : d === 3 ? 'Intermediate' : 'Advanced';
const map = new Map();

for (const item of $input.all()) {
  for (const s of (item.json.skills || [])) {
    if (!s || !s.skill) continue;
    const key = String(s.skill).trim().toLowerCase();
    const d = Math.max(1, Math.min(5, Number(s.difficulty) || 3));
    if (!map.has(key)) {
      map.set(key, {
        skill: String(s.skill).trim(),
        desskill: s.desskill || '',
        urlskill: s.urlskill || '',
        total: d,
        count: 1
      });
    } else {
      const m = map.get(key);
      m.total += d;
      m.count += 1;
      if (!m.desskill && s.desskill) m.desskill = s.desskill;
    }
  }
}

const out = [...map.values()]
  .map(m => {
    const difficulty = Math.round(m.total / m.count);
    return {
      skill: m.skill,
      difficulty,
      level: levelOf(difficulty),
      desskill: m.desskill,
      urlskill: m.urlskill
    };
  })
  .sort((a, b) => a.difficulty - b.difficulty || a.skill.localeCompare(b.skill))
  .map((s, i) => ({ week: i + 1, ...s }));

return out.length
  ? out.map(s => ({ json: s }))
  : [{ json: { skill: '', note: 'No skills found' } }];

const jobs = $('Code in JavaScript1').all().map(i => ({
  title: i.json.title,
  companyName: i.json.companyName,
  postedAt: i.json.postedAt,
  link: i.json.link,
  matchScore: i.json.matchScore,
  summary: i.json.summary
}));

const roadmap = $('Code in JavaScript2').all()
  .map(i => i.json)
  .filter(s => s.skill);

return [{ json: { jobs, roadmap } }];
